    {
      "sentence": "暴风雨来临前，阴云密布的长空显得格外压抑。",
      "tier": "T4"
    },
    {
      "sentence": "仰望深邃的长空，人类对宇宙的无限奥秘充满了向往。",
      "tier": "T5"
    },
    {
      "sentence": "落日的余晖将长空染成一片壮丽的绯红。",
      "tier": "T5"
    },
    {
      "sentence": "深邃的长空承载着无数代人对飞行的执着梦想。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "常年",
      "explanation": "“常年”（chángnián）与“长空”（chángkōng）声母和第一个字相同，但第二个字读音及词义完全不同，容易在快读时混淆。"
    },
    {
      "word": "长工",
      "explanation": "“长工”（chánggōng）与“长空”（chángkōng）仅在第二个字的声调上有细微差别（一声的“空”与一声的“工”同音但汉字不同，此处声调皆为阳平，实际易错音近词为“长功”），作为同音词常因字形相似被误读。"
    },
    {
      "word": "厂矿",
      "explanation": "“厂矿”（chǎngkuàng）的发音与“长空”（chángkōng）在声母和韵母搭配上有相似的听觉感受，非母语者容易听错。"
    }
  ],
  "primary_collocate": "划破",
  "collocation_distractors": [
    {
      "word": "建造",
      "explanation": "“建造”通常用于房屋、桥梁等实体建筑，而“长空”是自然天空，无法被人为建造。"
    },
    {
      "word": "咀嚼",
      "explanation": "“咀嚼”用于食物，与抽象或广阔的天空在语义上毫无关联。"
    },
    {
      "word": "书写",
      "explanation": "“书写”一般搭配文字、历史或篇章，不能用来直接搭配天空。"
    }
  ],
  "collocation_wrong_collocate": "开辟",
  "cloze_distractors": [
    {
      "word": "长城",
      "explanation": "“长城”是人工建造的古代军事防御工程，而句子语境需要一个表示天空的空间名词。"
    },
    {
      "word": "长江",
      "explanation": "“长江”是一条河流，虽然宏大，但无法承载“翱翔”或“划破”这种天空特有的动态。"
    },
    {
      "word": "长椅",
      "explanation": "“长椅”是供人坐的家具，放入句中会导致语义完全不通，属于严重错位。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他把这只长空放在了桌子上。",
      "reason": "“长空”是天空的意思，属于无法被移动或放置的宏观自然空间，不能作为宾语放在“放”字后面。"
    },
    {
      "sentence": "这件衣服的长空颜色非常好看。",
      "reason": "“长空”指天空，不能用来修饰衣物或指代服装的款式与布料。"
    },
    {
      "sentence": "长空了一整天，让人感到十分疲惫。",
      "reason": "“长空”是名词，不能直接当作动词使用来表达某种持续的动作或状态。"
    }
  ],
  "spot_incorrect": {
    "sentence": "战斗机迅速地掠过了长空，声音震耳欲聋。",
    "error_description": "“长空”本身是一个偏正或主谓结构的词，但在此处作为宾语时，句法搭配虽然勉强成立，然而原句中更习惯用“划破”而非单纯的“掠过了”来体现战斗机的动态。更明显的错误在于若将其误用为动词词性或错误重叠则不符合规范（此处设定的 planted error 为词性误用：‘美丽的长空’误写作‘长空美丽了天空’）。调整为更典型的语病：‘雄鹰在长空上飞翔。’应为‘在长空中’或‘翱翔长空’。修改后的句子：雄鹰在长空中翱翔。",
    "corrected_version": "雄鹰在长空中翱翔。"
  },
